void JumpApp(void) 
{
    __asm volatile ("LDR R1, =0x0");    
    __asm volatile ("LDR R2, [R1]");  
    __asm volatile ("MOV SP, R2"); 
    __asm volatile ("LDR R0, [R1,#4]"); 
    __asm volatile ("BX R0");  	
}


uint32_t mem_test_march_C2 (uint32_t startaddr, uint32_t length, uint32_t value_0,uint32_t value_1)
{
	int i; 
	uint32_t * ramaddr;
   
	ramaddr = (uint32_t *)startaddr;
   
	// step 0: W0
	for(i=0; i<length; i++)
	{
		ramaddr[i] = value_0;
	}


	// step 1: R0->W1->R1  ,address ++
	for(i=0; i<length; i++)
	{
		if( ramaddr[i] != value_0)	
		{
			return ( (uint32_t)ramaddr + (i *4) );   
		}   
		ramaddr[i] = value_1;	     
		if( ramaddr[i] != value_1)	 
		{
			return ( (uint32_t)ramaddr + (i *4) );    
		} 
	}

	// step 2: R1->W0->R0  ,address ++
	for(i=0; i<length; i++)
	{
		
		if( ramaddr[i] != value_1)	
		{
			return ( (uint32_t)ramaddr + (i *4) );    
		}   
		ramaddr[i] = value_0;	     
		if( ramaddr[i] != value_0)	 
		{
			return ( (uint32_t)ramaddr + (i *4) );   
		} 
	}

	// step 3: R0->W1->R1  ,address --
	for(i=length; i>0; i--)
	{
		i =i-1;
		if( ramaddr[i] != value_0)	
		{
			return ( (uint32_t)ramaddr + (i *4) );     
		}   
		ramaddr[i] = value_1;	     
		if( ramaddr[i] != value_1)	 
		{
			return ( (uint32_t)ramaddr + (i *4) );     
		} 
	}

	// step 4: R1->W0->R0  ,address --
	for(i=length; i>0; i--)
	{
		i =i-1;
		if( ramaddr[i] != value_1)	
		{
			return ( (uint32_t)ramaddr + (i *4) );        
		}   
		ramaddr[i] = value_0;	     
		if( ramaddr[i] != value_0)	 
		{
			return ( (uint32_t)ramaddr + (i *4) );     
		} 
	}

	// step 5: R0 
	for(i=0; i<length; i++)
	{
		if(ramaddr[i]!=value_0)
		{
			return ( (uint32_t)ramaddr + (i *4) );        
		} 
	}

	return 0;	 
}

// test 256 bytes one time 
uint32_t sram_byte_test(uint32_t start_addr)
{
    uint32_t i; 
    
    for(i = 0; i < 256; i++)
    {
        *(volatile uint8_t *)(start_addr + i) = i; 
    }
    
    for(i = 0; i < 256; i++)
    {
        if (i != *(volatile uint8_t *)(start_addr + i) )
        {
            return 1;   
        }
    }
    
    return 0;    
}  

// test 512 bytes one time  
uint32_t sram_half_word_test(uint32_t start_addr)
{
    uint32_t i, j;   
    
    j = start_addr;  
    
    for(i = 0; i < 256; i++)   
    {
        *(volatile uint16_t *)(j) = i + (i << 8);     
        j = j + 2;     
    }
    
    j = start_addr;   
    for(i = 0; i < 256; i++)   
    {
        if ( (i + (i << 8) ) != *(volatile uint16_t *)(j) )
        {
            return 2;   
        }
        
        j = j + 2;   
    }
    
    return 0;    
}  



//length ：数据长度，单位为WORD
uint32_t sram_test(uint32_t startaddr, uint32_t length)
{
 	uint32_t result=0, i, num;  

	result=mem_test_march_C2 (startaddr, length, 0x00000000,0xffffffff);
	if(result)  
	{
//		result += (0x0a<<8);
		return result;
	}

	result=mem_test_march_C2 (startaddr, length, 0x0000ffff,0xffff0000);
	if(result)  
	{
//		result += (0x0b<<8);
		return result;
	}

	result=mem_test_march_C2 (startaddr, length, 0x55555555,0xaaaaaaaa);
	if(result)  
	{
//		result += (0x0c<<8);
		return result;
	}

	result=mem_test_march_C2 (startaddr, length, 0x33333333,0xcccccccc);
	if(result)  
	{
//		result += (0x0b<<8);  
		return result;
	}
    
    num = (length * 4)/256;     
    for(i = 0; i < num;)
    {
        result = sram_byte_test(startaddr + i);  
        
        if (0 != result)  
        {
            return result;   
        }
        
        i += 256;   
    }
    
    num = (length * 4)/512;     
    for(i = 0; i < num;)
    {
        result = sram_half_word_test(startaddr + i);  
        
        if (0 != result)  
        {
            return result;   
        }
        
        i += 512;   
    }

	return 0;
}   


DMA_HandleTypeDef DMA1_Ch0Handle;
uint32_t g_dma_destBuf[256];  

void DMA_Init(void)
{
    DMA1_Ch0Handle.Instance             = DMA1_Channel0;
	DMA1_Ch0Handle.Init.Mode            = DMA_MODE_NORMAL;
	DMA1_Ch0Handle.Init.DataFlow        = DMA_DATAFLOW_M2M;
	DMA1_Ch0Handle.Init.ReqID           = DMA1_REQ_M2M;
	DMA1_Ch0Handle.Init.SrcIncDec       = DMA_SRCINCDEC_INC;
	DMA1_Ch0Handle.Init.DestIncDec      = DMA_DESTINCDEC_INC;
	DMA1_Ch0Handle.Init.SrcWidth        = DMA_SRCWIDTH_WORD;
	DMA1_Ch0Handle.Init.DestWidth       = DMA_DESTWIDTH_WORD;
	DMA1_Ch0Handle.Init.SrcBurst        = DMA_SRCBURST_1;
	DMA1_Ch0Handle.Init.DestBurst       = DMA_DESTBURST_1;
	DMA1_Ch0Handle.Init.Lock            = DISABLE;
	DMA1_Ch0Handle.Init.SrcMaster       = DMA_SRCMASTER_1;
	DMA1_Ch0Handle.Init.DestMaster      = DMA_DESTMASTER_1;
	
	HAL_DMA_Init(&DMA1_Ch0Handle);
}

/************************************************************************
 * function   : printf_buff_word
 * Description: printf data block by word
 * input :
 *         UINT8* buff: buff
 *         UINT32 length: word length
 * return: none
 ************************************************************************/
void printf_buff_word(uint32_t* buff, uint32_t length)
{
	uint32_t i;

	for(i=0;i<length;i++)
	{
		printf("%.8x ",buff[i]);	
	}
	printf("\n");
}



